create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.ledgers (id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name)) between 1 and 100), created_by uuid not null references auth.users, created_at timestamptz not null default now());
create table public.ledger_members (ledger_id uuid not null references public.ledgers on delete cascade, user_id uuid not null references auth.users on delete cascade, role text not null check(role in ('owner','member')), joined_at timestamptz not null default now(), primary key(ledger_id,user_id));
create table public.categories (id uuid primary key default gen_random_uuid(), ledger_id uuid not null references public.ledgers on delete cascade, name text not null check(length(trim(name)) between 1 and 100), type text not null check(type in ('income','expense')), unique(id,ledger_id));
create table public.transactions (id uuid primary key default gen_random_uuid(), ledger_id uuid not null references public.ledgers on delete cascade, type text not null check(type in ('income','expense','transfer')), amount bigint not null check(amount between 1 and 9007199254740991), occurred_on date not null, category_id uuid, memo text not null default '' check(length(memo)<=1000), created_by uuid not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(category_id,ledger_id) references public.categories(id,ledger_id), foreign key(ledger_id,created_by) references public.ledger_members(ledger_id,user_id));
create index on public.transactions(ledger_id,occurred_on desc);
create table public.monthly_budgets (ledger_id uuid not null references public.ledgers on delete cascade, month date not null check(extract(day from month)=1), amount bigint not null check(amount between 0 and 9007199254740991), primary key(ledger_id,month));
create table public.ledger_invites (code text primary key, ledger_id uuid not null references public.ledgers on delete cascade, expires_at timestamptz not null default now()+interval '7 days', used_at timestamptz);
create table public.imports (id uuid primary key default gen_random_uuid(), ledger_id uuid not null references public.ledgers on delete cascade, owner_id uuid not null references auth.users, source text not null check(source in ('notification','sms','csv','manual')), raw_text text not null check(length(raw_text) between 1 and 10000), dedupe_hash text not null, amount bigint check(amount between 1 and 9007199254740991), occurred_on date, merchant text, type text check(type in ('income','expense')), status text not null default 'pending' check(status in ('pending','accepted','ignored')), transaction_id uuid references public.transactions, created_at timestamptz not null default now(), unique(owner_id,ledger_id,dedupe_hash), foreign key(ledger_id,owner_id) references public.ledger_members(ledger_id,user_id));
create table public.device_tokens (id uuid primary key default gen_random_uuid(), ledger_id uuid not null, owner_id uuid not null, token_hash text not null unique, name text not null default '', created_at timestamptz not null default now(), last_used_at timestamptz, revoked_at timestamptz, foreign key(ledger_id,owner_id) references public.ledger_members(ledger_id,user_id));
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(), ledger_id uuid not null, owner_id uuid not null, endpoint text not null unique, p256dh text not null, auth text not null, created_at timestamptz not null default now(), foreign key(ledger_id,owner_id) references public.ledger_members(ledger_id,user_id));
create function public.is_ledger_member(target uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.ledger_members where ledger_id=target and user_id=auth.uid()) $$;
revoke all on function public.is_ledger_member(uuid) from public; grant execute on function public.is_ledger_member(uuid) to authenticated;
alter table public.ledgers enable row level security;
alter table public.ledger_members enable row level security;
alter table public.categories enable row level security;
alter table public.transactions enable row level security;
alter table public.monthly_budgets enable row level security;
alter table public.ledger_invites enable row level security;
alter table public.imports enable row level security;
alter table public.device_tokens enable row level security;
alter table public.push_subscriptions enable row level security;
create policy read_ledgers on public.ledgers for select to authenticated using(public.is_ledger_member(id));
create policy read_members on public.ledger_members for select to authenticated using(public.is_ledger_member(ledger_id));
create policy category_access on public.categories for all to authenticated using(public.is_ledger_member(ledger_id)) with check(public.is_ledger_member(ledger_id));
create policy transaction_read on public.transactions for select to authenticated using(public.is_ledger_member(ledger_id));
create policy transaction_insert on public.transactions for insert to authenticated with check(public.is_ledger_member(ledger_id) and created_by=auth.uid());
create policy transaction_update on public.transactions for update to authenticated using(public.is_ledger_member(ledger_id)) with check(public.is_ledger_member(ledger_id));
create policy transaction_delete on public.transactions for delete to authenticated using(public.is_ledger_member(ledger_id));
create policy budgets_access on public.monthly_budgets for all to authenticated using(public.is_ledger_member(ledger_id)) with check(public.is_ledger_member(ledger_id));
create policy imports_read on public.imports for select to authenticated using(owner_id=auth.uid() and public.is_ledger_member(ledger_id));
create policy device_read on public.device_tokens for select to authenticated using(owner_id=auth.uid() and public.is_ledger_member(ledger_id));
create policy push_access on public.push_subscriptions for all to authenticated using(owner_id=auth.uid() and public.is_ledger_member(ledger_id)) with check(owner_id=auth.uid() and public.is_ledger_member(ledger_id));
create function public.protect_transaction() returns trigger language plpgsql set search_path='' as $$ begin if new.created_by<>old.created_by or new.ledger_id<>old.ledger_id then raise exception 'Transaction identity cannot change'; end if; new.updated_at:=now(); return new; end $$;
create trigger transaction_identity before update on public.transactions for each row execute function public.protect_transaction();
create function public.create_ledger(ledger_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.ledgers(name,created_by) values(ledger_name,auth.uid()) returning id into result; insert into public.ledger_members(ledger_id,user_id,role) values(result,auth.uid(),'owner'); return result; end $$;
create function public.create_invite(target_ledger uuid) returns text language plpgsql security definer set search_path='' as $$ declare code_value text; begin if not public.is_ledger_member(target_ledger) then raise exception 'Access denied'; end if; code_value:=encode(extensions.gen_random_bytes(16),'hex'); insert into public.ledger_invites(code,ledger_id) values(code_value,target_ledger); return code_value; end $$;
create function public.join_ledger(invite_code text) returns uuid language plpgsql security definer set search_path='' as $$ declare target uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select ledger_id into target from public.ledger_invites where code=invite_code and used_at is null and expires_at>now() for update; if target is null then raise exception 'Invalid invite'; end if; perform pg_advisory_xact_lock(hashtextextended(target::text,0)); if not exists(select 1 from public.ledger_members where ledger_id=target and user_id=auth.uid()) then if (select count(*) from public.ledger_members where ledger_id=target)>=2 then raise exception 'Ledger is full'; end if; insert into public.ledger_members(ledger_id,user_id,role) values(target,auth.uid(),'member'); end if; update public.ledger_invites set used_at=now() where code=invite_code; return target; end $$;
create function public.resolve_import(item_id uuid, action text, item_type text default null, item_amount bigint default null, item_date date default null, item_category uuid default null, item_memo text default '') returns uuid language plpgsql security definer set search_path='' as $$ declare item public.imports%rowtype; new_id uuid; begin select * into item from public.imports where id=item_id and owner_id=auth.uid() for update; if item.id is null or not public.is_ledger_member(item.ledger_id) then raise exception 'Access denied'; end if; if item.status<>'pending' then raise exception 'Already processed'; end if; if action='ignore' then update public.imports set status='ignored' where id=item_id; return null; elsif action='accept' then insert into public.transactions(ledger_id,type,amount,occurred_on,category_id,memo,created_by) values(item.ledger_id,coalesce(item_type,item.type),coalesce(item_amount,item.amount),coalesce(item_date,item.occurred_on),item_category,coalesce(item_memo,''),auth.uid()) returning id into new_id; update public.imports set status='accepted',transaction_id=new_id where id=item_id; return new_id; else raise exception 'Invalid action'; end if; end $$;
revoke all on function public.create_ledger(text),public.create_invite(uuid),public.join_ledger(text),public.resolve_import(uuid,text,text,bigint,date,uuid,text) from public;
grant execute on function public.create_ledger(text),public.create_invite(uuid),public.join_ledger(text),public.resolve_import(uuid,text,text,bigint,date,uuid,text) to authenticated;
alter publication supabase_realtime add table public.transactions,public.categories,public.monthly_budgets,public.ledger_members,public.imports;
